cd "$(pwd)" && python3 -c '
import csv, json, time
from databricks.sdk import WorkspaceClient
w=WorkspaceClient(); INDEX="workspace.mlpab072c27.itemsf3ae88"
queries=[]
with open("data/queries.csv") as f:
    for r in csv.DictReader(f):
        queries.append((r["query_id"],[float(x) for x in json.loads(r["embedding"])]))
def q(vec):
    for attempt in range(30):
        try:
            return w.vector_search_indexes.query_index(index_name=INDEX,columns=["item_id"],query_vector=vec,num_results=5)
        except Exception as e:
            if "not ready" in str(e):
                time.sleep(10); continue
            raise
    raise RuntimeError("index never ready")
neighbors={}
for qid,vec in queries:
    res=q(vec)
    rows=res.result.data_array
    neighbors[qid]=[row[0] for row in rows]
    print(qid,neighbors[qid],[round(row[-1],4) for row in rows],flush=True)
out={"store":INDEX,"neighbors":neighbors}
with open("submission/answers.json","w") as f:
    json.dump(out,f,indent=2)
print("WROTE",len(neighbors),"queries; sizes set:",set(len(v) for v in neighbors.values()))
'
